import { isAlive } from '@jbrowse/mobx-state-tree'
import {
  fetchAlphaFoldComplexModel,
  fetchAlphaFoldModels,
  getAlphaFoldStructureUrl,
  pickAlphaFoldModel,
} from 'p2s_mapper'

import { loadStructureData } from './loadStructureData'
import { removeMolstarStructure } from './removeStructure'

import type StructureModel from './structureModel'
import type { IAnyStateTreeNode, Instance } from '@jbrowse/mobx-state-tree'
import type { PluginContext } from 'molstar/lib/mol-plugin/context'
import type { AlphaFoldComplexModel, AlphaFoldModel } from 'p2s_mapper'

type StructureInstance = Instance<typeof StructureModel>

export type AlphaFoldModelFetcher = (
  uniprotId: string,
) => Promise<AlphaFoldModel[]>

export type AlphaFoldComplexFetcher = (
  entity: string,
) => Promise<AlphaFoldComplexModel | undefined>

export type StructureLoaderHost = IAnyStateTreeNode & {
  readonly molstarPluginContext: PluginContext | undefined
  readonly structures: StructureInstance[]
}

/**
 * Builds the body of the autorun that loads structures into Molstar.
 *
 * The returned callback is synchronous on purpose: MobX only tracks
 * observables read before the first `await`, so an async autorun body would
 * stop reacting to later structures/plugin changes. Instead it reads its
 * dependencies synchronously and dispatches a guarded fire-and-forget load for
 * each structure that is neither loaded nor already loading. The guards handle
 * the lifecycle hazards of an external GPU resource:
 *
 *   - a non-observable in-flight map, from each structure to the plugin it is
 *     loading into, stops a re-entrant run from starting a duplicate load into
 *     the same plugin, while a plugin swapped in mid-load starts at once;
 *   - a load whose plugin was replaced or whose model was destroyed while
 *     awaiting has its result discarded rather than written into a torn-down
 *     plugin;
 *   - if the plugin was merely swapped (e.g. a view remount), the structure is
 *     reloaded into the current plugin so it isn't left stranded unloaded;
 *   - a loaded structure whose `assembly` no longer matches the one it was
 *     built with leaves Mol* and loads again, so every reaction keyed on its
 *     Mol* structures reaches the new chains.
 */
export function makeStructureLoader(
  host: StructureLoaderHost,
  fetchModels: AlphaFoldModelFetcher = fetchAlphaFoldModels,
  fetchComplex: AlphaFoldComplexFetcher = fetchAlphaFoldComplexModel,
) {
  const loadingIn = new Map<StructureInstance, PluginContext>()
  const failedIn = new WeakMap<
    StructureInstance,
    { plugin: PluginContext; attempt: number }
  >()

  /** A failure stands until the plugin changes or the structure asks to
   * retry, which bumps its `loadAttempt`. That is read first, whatever the
   * answer: a failure lands outside the autorun, so a run that skipped the
   * read would leave a retry unheard. */
  function failedInto(structure: StructureInstance, plugin: PluginContext) {
    const { loadAttempt } = structure
    const failed = failedIn.get(structure)
    return failed?.plugin === plugin && failed.attempt === loadAttempt
  }

  /** The AlphaFold id a structure still has to turn into a file, if any. */
  function unresolvedId(structure: StructureInstance) {
    const { url, data, uniprotId, alphaFoldComplexId } = structure
    return url !== undefined || data !== undefined
      ? undefined
      : alphaFoldComplexId
        ? { kind: 'complex' as const, id: alphaFoldComplexId }
        : uniprotId
          ? { kind: 'accession' as const, id: uniprotId }
          : undefined
  }

  /** A complex's file carries a model version that moves, so it is asked
   * for, like an accession's */
  async function resolveComplexUrl(entity: string) {
    const model = await fetchComplex(entity)
    if (!model) {
      throw new Error(`AlphaFold DB has no complex ${entity}`)
    }
    return model.url
  }

  /**
   * Which AlphaFold file an accession opens. Asked rather than spelled: a
   * protein folded past the length cap has no F1 fragment, and the model
   * version moves, so a hardcoded name 404s. The accession's own model wins,
   * so `P04637` opens the canonical model beside an isoform's transcript and
   * `P04637-4` the isoform's. Only an accession AlphaFold DB folded as
   * isoforms alone goes to the picker, with the transcript's translation.
   *
   * The two ways that can come back empty are not the same answer. An
   * unreachable API says nothing about the accession, so the spelled canonical
   * filename is worth a try — it is what this opened before it asked at all.
   * An API that answers with no models has told us there is nothing to open,
   * and spelling a filename anyway just turns that into a 404 the reader has
   * to diagnose.
   *
   * The resolved url is kept only once its file loads, so a spelled filename
   * that 404s leaves the next attempt asking the API again.
   */
  async function resolveAlphaFoldUrl(
    structure: StructureInstance,
    uniprotId: string,
  ) {
    const models = await fetchModels(uniprotId).catch(() => undefined)
    if (!isAlive(structure)) {
      return undefined
    }
    if (models === undefined) {
      return getAlphaFoldStructureUrl(uniprotId)
    }
    const picked =
      models.find(m => m.accession === uniprotId) ??
      pickAlphaFoldModel(models, {
        transcript: { seq: structure.userProvidedTranscriptSequence },
      })
    if (!picked) {
      throw new Error(`AlphaFold DB has no model for ${uniprotId}`)
    }
    return picked.url
  }

  async function loadResolvedFile(
    structure: StructureInstance,
    plugin: PluginContext,
    url: string,
  ) {
    structure.setResolvedUrl(url)
    const data = await loadStructureData({ structure, plugin, url })
    if (isAlive(structure)) {
      structure.setUrl(url)
    }
    return data
  }

  function loadResolved(
    structure: StructureInstance,
    plugin: PluginContext,
    url: string | undefined,
  ) {
    return url !== undefined && isAlive(structure)
      ? loadResolvedFile(structure, plugin, url)
      : undefined
  }

  function settle(structure: StructureInstance, plugin: PluginContext) {
    if (loadingIn.get(structure) === plugin) {
      loadingIn.delete(structure)
    }
  }

  function retryIn(structure: StructureInstance, current: PluginContext) {
    if (loadingIn.get(structure) !== current) {
      loadInto(structure, current)
    }
  }

  function loadInto(structure: StructureInstance, plugin: PluginContext) {
    loadingIn.set(structure, plugin)
    const attempt = structure.loadAttempt
    // A retry — a plugin swap, a remount — starts over, so the last attempt's
    // failure goes with it. Left in place it also reported the structure as
    // settled for the whole of the retry, since `loading` reads it.
    structure.setError(undefined)
    structure.setResolvedUrl(undefined)
    // a structure that already knows its file dispatches synchronously, so the
    // in-flight guard covers it before the autorun body returns
    const unresolved = unresolvedId(structure)
    const loaded =
      unresolved === undefined
        ? loadStructureData({ structure, plugin })
        : (unresolved.kind === 'complex'
            ? resolveComplexUrl(unresolved.id)
            : resolveAlphaFoldUrl(structure, unresolved.id)
          ).then(url => loadResolved(structure, plugin, url))
    loaded
      .then(data => {
        if (!data) {
          settle(structure, plugin)
          return
        }
        if (!isAlive(structure)) {
          // Removed while it was loading. The load still put a trajectory in
          // Mol*, and no model owns it any more, so it would stay on the
          // canvas and join the next superposition as a structure the view
          // does not know it has.
          settle(structure, plugin)
          removeMolstarStructure({
            plugin,
            molstarStructure: data.molstarStructures?.[0],
          }).catch((e: unknown) => {
            console.error(e)
          })
          return
        }
        const current = host.molstarPluginContext
        if (current === plugin) {
          structure.setStructureData(data)
        }
        settle(structure, plugin)
        if (current && current !== plugin && !structure.loadedToMolstar) {
          retryIn(structure, current)
        }
      })
      .catch((e: unknown) => {
        settle(structure, plugin)
        if (!isAlive(host) || !isAlive(structure)) {
          return
        }
        const current = host.molstarPluginContext
        if (current && current !== plugin) {
          // a plugin torn down mid-load rejects too; the structure belongs in
          // the current one, not in an error
          retryIn(structure, current)
        } else {
          // the structure carries its own failure: a view-wide "Failed to
          // fetch" names neither which structure nor what it was fetching
          failedIn.set(structure, { plugin, attempt })
          structure.setLoadError(e)
          console.error(e)
        }
      })
  }

  function unloadOtherAssembly(
    structure: StructureInstance,
    plugin: PluginContext,
  ) {
    const { molstarStructure } = structure
    structure.clearMolstarStructures()
    removeMolstarStructure({ plugin, molstarStructure }).catch((e: unknown) => {
      console.error(e)
    })
  }

  return function loadPendingStructures() {
    const { structures, molstarPluginContext } = host
    if (molstarPluginContext) {
      for (const structure of structures) {
        if (
          structure.loadedToMolstar &&
          structure.assembly !== structure.loadedAssembly
        ) {
          unloadOtherAssembly(structure, molstarPluginContext)
        }
        const failed = failedInto(structure, molstarPluginContext)
        if (
          !structure.loadedToMolstar &&
          loadingIn.get(structure) !== molstarPluginContext &&
          !failed
        ) {
          loadInto(structure, molstarPluginContext)
        }
      }
    }
  }
}
